#!/usr/bin/env bash
# sum prints the sum of its integer arguments, or 0 with none; bash-only (uses ${!i}).
# Usage: source calc.sh; sum 1 2 3   # prints 6. Decimals like 1.5 are an arithmetic error.
sum() {
  local total=0 i
  for ((i = 1; i <= $#; i++)); do
    total=$((total + ${!i}))
  done
  echo "$total"
}
